sys_script_include.script:
var BudgetUtils = Class.create();
BudgetUtils.prototype = {
    initialize: function() {},

    // 1. Calculate total budget for an event
    getTotalBudgetByEvent: function(eventID) {
        var gr = new GlideAggregate('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventID);
        gr.addAggregate('SUM', 'u_total_budget');
        gr.query();
        if (gr.next()) {
            return 'Total Budget: ' + gr.getAggregate('SUM', 'u_total_budget');
        }
        return 'No budget records found';
    },

    // 2. Check if a budget is approved
    isBudgetApproved: function(eventID) {
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        if (gr.next()) {
            return gr.u_status == 'approved' ? 'Budget Approved' : 'Budget Not Approved';
        }
        return 'Budget not found';
    },

    // 3. Fetch budget details by event ID
    getBudgetDetailsByEvent: function(eventID) {
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.u_total_budget + ' | ' + gr.u_amount_spent + ' | ' + gr.u_amount_remaining);
        }
        return result.length ? result.join('\n') : 'No budget details found';
    },
	// 4. Calculate remaining budget for an event
	getRemainingBudget: function(eventID) {
    var gr = new GlideAggregate('x_1790227_event_ma_budget');
    gr.addQuery('u_event_id.number', eventID);
    gr.addAggregate('SUM', 'u_amount_remaining');
    gr.query();
    if (gr.next()) {
        return 'Remaining Budget: ' + gr.getAggregate('SUM', 'u_amount_remaining');
    }
    return 'No remaining budget data found';
},


    type: 'BudgetUtils'
};
